<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { apiRequest } from '@/services/api'
import type { CandidateProfile, Education, Experience, Language } from '@/services/candidate'
const props = defineProps<{ profile: CandidateProfile; initialEdit?: boolean }>()
const emit = defineEmits<{ updated: [profile: CandidateProfile] }>()
const editing = ref(false); const busy = ref(false); const error = ref(''); const success = ref('')
const draft = reactive({ education: [] as Education[], experience: [] as Experience[], languages: [] as Language[] })
function sync() { Object.assign(draft, JSON.parse(JSON.stringify({ education: props.profile.education ?? [], experience: props.profile.experience ?? [], languages: props.profile.languages ?? [] }))) }
watch(() => props.profile, () => { if (!editing.value) sync() }, { immediate: true })
function edit() { sync(); error.value = ''; success.value = ''; editing.value = true }
onMounted(() => { if (props.initialEdit) edit() })
function addEducation() { draft.education.push({ school: '', degree: '', fieldOfStudy: '', startDate: '', endDate: '', description: '' }) }
function addExperience() { draft.experience.push({ company: '', position: '', employmentType: 'Full-time', startDate: '', endDate: '', current: false, description: '' }) }
async function save() {
  if (busy.value) return
  busy.value = true; error.value = ''; success.value = ''
  try {
    for (const entry of [...draft.education, ...draft.experience]) if (entry.endDate && entry.endDate < entry.startDate) throw new Error('End date cannot be before start date.')
    const { profile } = await apiRequest<{ profile: CandidateProfile }>('/account/profile', { method: 'PATCH', body: JSON.stringify(draft) })
    emit('updated', profile); editing.value = false; success.value = 'Professional background updated.'
  } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to save your background.' }
  finally { busy.value = false }
}
function period(start: string, end: string, current = false) { return `${start.slice(0, 7)} — ${current ? 'Present' : end ? end.slice(0, 7) : 'Ongoing'}` }
</script>
<template>
  <section class="background-card" aria-labelledby="background-heading">
    <header><div><h2 id="background-heading">Your professional background</h2><p>The experience, education, and languages you bring.</p></div><button v-if="!editing" class="text-button" @click="edit">Edit background</button></header>
    <p v-if="success" role="status" class="background-success">{{ success }}</p>
    <form v-if="editing" @submit.prevent="save">
      <fieldset :disabled="busy">
        <section id="experience" class="background-section"><h3>Experience</h3><article v-for="(entry, index) in draft.experience" :key="index" class="entry-editor"><div class="entry-title"><strong>Experience {{ index + 1 }}</strong><button type="button" class="remove-button" :aria-label="`Remove experience ${index + 1}`" @click="draft.experience.splice(index, 1)">Remove</button></div><div class="field-grid"><label>Company<input v-model="entry.company" required maxlength="160" /></label><label>Position<input v-model="entry.position" required maxlength="160" /></label><label>Employment type<select v-model="entry.employmentType"><option v-for="type in ['Full-time', 'Part-time', 'Contract', 'Internship', 'Freelance', 'Temporary']" :key="type">{{ type }}</option></select></label><label>Start date<input v-model="entry.startDate" type="date" required :max="new Date().toISOString().slice(0, 10)" /></label><label v-if="!entry.current">End date<input v-model="entry.endDate" type="date" :min="entry.startDate" /></label><label class="checkbox-label"><input v-model="entry.current" type="checkbox" @change="entry.current && (entry.endDate = '')" /> I currently work here</label><label class="full-field">Description<textarea v-model="entry.description" rows="3" maxlength="2000" /></label></div></article><button v-if="draft.experience.length < 20" type="button" class="add-button" @click="addExperience">+ Add experience</button></section>
        <section id="education" class="background-section"><h3>Education</h3><article v-for="(entry, index) in draft.education" :key="index" class="entry-editor"><div class="entry-title"><strong>Education {{ index + 1 }}</strong><button type="button" class="remove-button" :aria-label="`Remove education ${index + 1}`" @click="draft.education.splice(index, 1)">Remove</button></div><div class="field-grid"><label>School or university<input v-model="entry.school" required maxlength="160" /></label><label>Degree<input v-model="entry.degree" required maxlength="160" /></label><label class="full-field">Field of study<input v-model="entry.fieldOfStudy" maxlength="160" /></label><label>Start date<input v-model="entry.startDate" type="date" required :max="new Date().toISOString().slice(0, 10)" /></label><label>End date<input v-model="entry.endDate" type="date" :min="entry.startDate" /><small>Leave empty if ongoing</small></label><label class="full-field">Description<textarea v-model="entry.description" rows="3" maxlength="2000" /></label></div></article><button v-if="draft.education.length < 20" type="button" class="add-button" @click="addEducation">+ Add education</button></section>
        <section class="background-section"><h3>Languages</h3><div v-for="(language, index) in draft.languages" :key="index" class="language-editor"><label>Language<input v-model="language.name" required maxlength="60" placeholder="e.g. Khmer" /></label><label>Proficiency<select v-model="language.proficiency"><option v-for="level in ['Basic', 'Conversational', 'Professional', 'Fluent', 'Native']" :key="level">{{ level }}</option></select></label><button type="button" class="remove-button" :aria-label="`Remove language ${index + 1}`" @click="draft.languages.splice(index, 1)">Remove</button></div><button v-if="draft.languages.length < 20" type="button" class="add-button" @click="draft.languages.push({ name: '', proficiency: 'Professional' })">+ Add language</button></section>
      </fieldset>
      <p v-if="error" role="alert" class="background-error">{{ error }}</p><footer><button type="button" class="add-button" :disabled="busy" @click="editing = false; sync()">Discard</button><button class="save-button" :disabled="busy">{{ busy ? 'Saving…' : 'Save background' }}</button></footer>
    </form>
    <template v-else>
      <section class="background-section"><h3>Experience</h3><article v-for="(entry, index) in profile.experience" :key="index" class="history-entry"><h4>{{ entry.position }}</h4><p>{{ entry.company }} · {{ entry.employmentType }}</p><small>{{ period(entry.startDate, entry.endDate, entry.current) }}</small><p v-if="entry.description" class="entry-description">{{ entry.description }}</p></article><p v-if="!profile.experience?.length" class="empty-copy">Add a role, internship, or freelance project to show your experience.</p></section>
      <section class="background-section"><h3>Education</h3><article v-for="(entry, index) in profile.education" :key="index" class="history-entry"><h4>{{ entry.school }}</h4><p>{{ entry.degree }}{{ entry.fieldOfStudy ? ` · ${entry.fieldOfStudy}` : '' }}</p><small>{{ period(entry.startDate, entry.endDate) }}</small><p v-if="entry.description" class="entry-description">{{ entry.description }}</p></article><p v-if="!profile.education?.length" class="empty-copy">Include your education, training, or qualifications.</p></section>
      <section class="background-section"><h3>Languages</h3><div v-if="profile.languages?.length" class="language-list"><span v-for="language in profile.languages" :key="language.name"><strong>{{ language.name }}</strong><small>{{ language.proficiency }}</small></span></div><p v-else class="empty-copy">Let recruiters know which languages you use.</p></section>
    </template>
  </section>
</template>
<style scoped>
.background-card { padding: 24px; border: 1px solid #ebe8f3; border-radius: 15px; background: white; color: #26304d; }header, .entry-title, footer { display: flex; justify-content: space-between; align-items: start; gap: 14px; }h2 { font-size: 18px; font-weight: 700; letter-spacing: -.02em; }header p { font-size: 13px; color: #737c95; margin-top: 6px; line-height: 1.6; }h3 { font-size: 14px; font-weight: 700; margin-bottom: 15px; }h4 { font-size: 15px; font-weight: 600; }.background-section { border-top: 1px solid #eeebf5; padding-top: 24px; margin-top: 24px; }.text-button { color: #4e35c4; font-size: 12px; font-weight: 600; white-space: nowrap; }.empty-copy, .history-entry p { color: #6b748c; font-size: 13px; line-height: 1.8; }.history-entry { padding: 0 0 20px 16px; border-left: 2px solid #dfd8f7; margin-bottom: 15px; }.history-entry:last-child { padding-bottom: 0; margin-bottom: 0; }.history-entry small { display: block; margin: 5px 0; font-size: 12px; color: #8a91a4; }.entry-description { white-space: pre-line; overflow-wrap: anywhere; }.language-list { display: flex; flex-wrap: wrap; gap: 12px; }.language-list > span { display: grid; gap: 5px; background: #f6f4fb; border-radius: 8px; padding: 12px 16px; }.language-list strong { font-size: 13px; }.language-list small { color: #777f95; font-size: 12px; }fieldset { padding: 0; border: 0; min-width: 0; }.entry-editor { margin-bottom: 18px; padding: 18px; background: #f8f7fc; border-radius: 10px; }.entry-title { font-size: 13px; margin-bottom: 16px; }.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }label { display: grid; gap: 7px; font-size: 12px; font-weight: 600; }.full-field { grid-column: 1/-1; }input:not([type=checkbox]), select, textarea { width: 100%; min-width: 0; border: 1px solid #ddd8e9; border-radius: 7px; padding: 10px; background: white; font-size: 13px; font-weight: 400; }textarea { resize: vertical; }.checkbox-label { display: flex; align-items: center; gap: 8px; }.language-editor { display: grid; grid-template-columns: 1fr 1fr auto; gap: 12px; align-items: end; margin-bottom: 18px; }.remove-button { color: #a23e50; font-size: 12px; padding: 4px; }.add-button { color: #523bc5; font-size: 13px; padding: 10px 0; }.save-button { padding: 11px 17px; border-radius: 8px; background: #4930ce; color: white; font-size: 13px; font-weight: 600; }footer { margin-top: 24px; border-top: 1px solid #eeebf5; padding-top: 20px; justify-content: flex-end; align-items: center; }button { cursor: pointer; }button:disabled { opacity: .5; cursor: wait; }:is(button, input, select, textarea):focus-visible { outline: 2px solid #705aef; outline-offset: 3px; }.background-error, .background-success { margin-top: 16px; padding: 12px; border-radius: 8px; font-size: 13px; }.background-error { background: #fff0f1; color: #a03f53; }.background-success { background: #edf8f1; color: #367254; }@media(max-width: 600px) { .background-card { padding: 18px; }.field-grid { grid-template-columns: 1fr; }.language-editor { grid-template-columns: 1fr; }.entry-editor { padding: 14px; }header { flex-wrap: wrap; } }
</style>
